import http from 'node:http';
const script = `<script>(function(){const original=window.matchMedia.bind(window);window.matchMedia=function(q){if(q==='(prefers-reduced-motion: reduce)'){return {matches:true,media:q,onchange:null,addEventListener(){},removeEventListener(){},addListener(){},removeListener(){},dispatchEvent(){return true;}};}return original(q);};})();</script>`;
http.createServer((req,res)=>{http.get('http://127.0.0.1:3000'+req.url,{headers:{'accept-encoding':'identity'}},up=>{const chunks=[];up.on('data',c=>chunks.push(c));up.on('end',()=>{let data=Buffer.concat(chunks);const headers={...up.headers,'permissions-policy':'clipboard-write=()'};delete headers['content-length'];delete headers['transfer-encoding'];if((headers['content-type']||'').includes('text/html'))data=Buffer.from(data.toString().replace('<head>','<head>'+script));res.writeHead(up.statusCode,headers);res.end(data);});}).on('error',()=>{res.writeHead(502);res.end('Local preview unavailable');});}).listen(3001,'127.0.0.1',()=>process.stdout.write('Harness QA proxy ready on 3001\n'));

